FIXTURE="file://$(pwd)/web/usability/map-overlays-label.html"
npx --yes playwright screenshot \
  --browser chromium \
  --viewport-size "900,700" \
  --full-page \
  --wait-for-timeout 300 \
  "$FIXTURE" \
  web/usability/map-overlays-label.png

# Read check text via a tiny node/playwright evaluate or chrome
npx --yes playwright eval --help 2>&1 | head -5 || true

# Use node with playwright package from npx cache / install locally in /tmp
node << 'JS'
const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 900, height: 700 } });
  const fixture = 'file://' + path.resolve('web/usability/map-overlays-label.html');
  await page.goto(fixture);
  await page.waitForTimeout(200);
  const check = await page.locator('#check').innerText();
  console.log('CHECK:', check);
  if (!check.includes('ok=true')) process.exit(1);
  await browser.close();
})().catch(async (e) => {
  // playwright may not be resolvable from cwd; try dynamic import via npx path
  console.error('direct require failed:', e.message);
  process.exit(2);
});
